begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
select has_function('public','save_catalog_product',array['uuid','uuid','uuid','uuid','integer','jsonb'],'versioned catalog save exists');
select ok(not has_function_privilege('anon','public.save_catalog_product(uuid,uuid,uuid,uuid,integer,jsonb)','EXECUTE'),'anonymous RPC denied');
select ok(not has_function_privilege('authenticated','public.save_catalog_product(uuid,uuid,uuid,uuid,integer,jsonb)','EXECUTE'),'browser RPC denied');
insert into auth.users(id) values('b1000000-0000-4000-8000-000000000001'),('b1000000-0000-4000-8000-000000000002');
insert into public.staff_profiles(user_id,organization_id,role,active) values
('b1000000-0000-4000-8000-000000000001','a0000000-0000-0000-0000-000000000001','manager',true),
('b1000000-0000-4000-8000-000000000002','a0000000-0000-0000-0000-000000000001','staff',true);
create temporary table catalog_fixture(document jsonb);
insert into catalog_fixture values ('{"name":"Fixture keyboard","sku":null,"brand":null,"productType":"keyboard","descriptionText":null,"priceVnd":100000,"stockQuantity":null,"inStock":true,"active":true,"specifications":[{"name":"Switch","value":"Linear"}],"images":[{"id":"c1000000-0000-4000-8000-000000000010","url":"https://example.invalid/not-found.jpg","altText":null}],"variants":[]}');
grant select on catalog_fixture to service_role;
create function pg_temp.catalog_save(ver integer,doc jsonb default null,request uuid default gen_random_uuid(),actor uuid default 'b1000000-0000-4000-8000-000000000001') returns jsonb language sql as $$
 select public.save_catalog_product('a0000000-0000-0000-0000-000000000001',actor,request,'c1000000-0000-4000-8000-000000000001',ver,coalesce(doc,(select document from catalog_fixture)))
$$;
set local role service_role;
select throws_ok($$select pg_temp.catalog_save(0,null,gen_random_uuid(),'b1000000-0000-4000-8000-000000000002')$$,'42501','CATALOG_FORBIDDEN','staff cannot save via trusted RPC');
select lives_ok($$select pg_temp.catalog_save(0,null,'d1000000-0000-4000-8000-000000000001')$$,'manager creates aggregate');
select is((select version from public.products where id='c1000000-0000-4000-8000-000000000001'),1,'first version');
select is((select stock_quantity from public.products where id='c1000000-0000-4000-8000-000000000001'),null::integer,'unknown physical stock remains null');
select is((select source_name from public.products where id='c1000000-0000-4000-8000-000000000001'),'OneVoice manual','manual product is not fake GearVN');
select is((select current_price from public.product_content_context where product_id='c1000000-0000-4000-8000-000000000001'),100000::bigint,'AI context immediately sees saved price');
select is((select count(*) from public.content_ready_products where id='c1000000-0000-4000-8000-000000000001'),1::bigint,'non-laptop product eligible with facts');
select lives_ok($$select pg_temp.catalog_save(0,null,'d1000000-0000-4000-8000-000000000001')$$,'same request replays safely');
select is((select count(*) from public.catalog_product_edits where product_id='c1000000-0000-4000-8000-000000000001'),1::bigint,'replay creates no edit');
select is((select count(*) from public.audit_events where entity_id='c1000000-0000-4000-8000-000000000001'),1::bigint,'replay creates no audit');
select throws_ok($$select pg_temp.catalog_save(0,(select document||'{"name":"changed"}' from catalog_fixture),'d1000000-0000-4000-8000-000000000001')$$,'40001','CATALOG_REQUEST_CONFLICT','request ID cannot carry changed payload');
select throws_ok($$select pg_temp.catalog_save(0)$$,'40001','CATALOG_VERSION_CONFLICT','stale tab cannot overwrite');
select lives_ok($$select pg_temp.catalog_save(1,(select document||'{"priceVnd":250000}' from catalog_fixture))$$,'versioned price update');
select is((select current_price from public.product_content_context where product_id='c1000000-0000-4000-8000-000000000001'),250000::bigint,'AI context sees new price without cache');
select throws_ok($$select pg_temp.catalog_save(2,(select document||'{"priceVnd":-1}' from catalog_fixture))$$,'23514',null,'SQL rejects negative price');
select is((select version from public.products where id='c1000000-0000-4000-8000-000000000001'),2,'invalid save rolls back version');
select lives_ok($$select pg_temp.catalog_save(2,(select document||'{"active":false}' from catalog_fixture))$$,'softdisable product');
select is((select count(*) from public.content_ready_products where id='c1000000-0000-4000-8000-000000000001'),0::bigint,'disabled excluded from Studio');
select is((select count(*) from public.product_content_context where product_id='c1000000-0000-4000-8000-000000000001'),0::bigint,'disabled excluded from AI');
select lives_ok($$select pg_temp.catalog_save(3,(select document||'{"stockQuantity":0,"inStock":true}' from catalog_fixture))$$,'zero quantity availability normalized');
select is((select in_stock from public.products where id='c1000000-0000-4000-8000-000000000001'),false,'zero stock cannot remain available');
select lives_ok($$select pg_temp.catalog_save(4,(select document||'{"variants":[{"id":"c1000000-0000-4000-8000-000000000020","name":"A","sku":null,"priceVnd":200000,"stockQuantity":3,"inStock":true,"active":true,"imageUrl":null},{"id":"c1000000-0000-4000-8000-000000000021","name":"B","sku":null,"priceVnd":300000,"stockQuantity":null,"inStock":true,"active":true,"imageUrl":null}]}' from catalog_fixture))$$,'variants created');
select is((select stock_quantity from public.products where id='c1000000-0000-4000-8000-000000000001'),null::integer,'any unknown active variant keeps parent unknown');
select lives_ok($$select pg_temp.catalog_save(5,(select document||'{"variants":[{"id":"c1000000-0000-4000-8000-000000000020","name":"A","sku":null,"priceVnd":200000,"stockQuantity":3,"inStock":true,"active":true,"imageUrl":null},{"id":"c1000000-0000-4000-8000-000000000021","name":"B","sku":null,"priceVnd":300000,"stockQuantity":0,"inStock":true,"active":true,"imageUrl":null}]}' from catalog_fixture))$$,'known variant quantities');
select is((select stock_quantity from public.products where id='c1000000-0000-4000-8000-000000000001'),3,'parent is physical aggregate not second bucket');
select is((select in_stock from public.product_variants where id='c1000000-0000-4000-8000-000000000021'),false,'zero variant stock overrides hint');
select lives_ok($$select pg_temp.catalog_save(6)$$,'omitted variants disabled, not deleted');
select is((select count(*) from public.product_variants where product_id='c1000000-0000-4000-8000-000000000001'),2::bigint,'variant history retained');
select is((select count(*) from public.product_variants where product_id='c1000000-0000-4000-8000-000000000001' and disabled_at is null),0::bigint,'no active variants after removal');
select is((select stock_quantity from public.products where id='c1000000-0000-4000-8000-000000000001'),0,'no active variants means no sellable inventory');
insert into public.audit_events(organization_id,actor_kind,action,entity_type,entity_id,reason,correlation_id,idempotency_key) values('a0000000-0000-0000-0000-000000000001','system','test.fixture','product','c1000000-0000-4000-8000-000000000001','test.fixture','d1000000-0000-4000-8000-000000000099','d1000000-0000-4000-8000-000000000099');
select throws_ok($$select pg_temp.catalog_save(7,(select document||'{"name":"MUST ROLLBACK"}' from catalog_fixture),'d1000000-0000-4000-8000-000000000099')$$,'23505',null,'audit failure aborts entire save');
select is((select name from public.products where id='c1000000-0000-4000-8000-000000000001'),'Fixture keyboard','product rolled back with audit');
select is((select version from public.products where id='c1000000-0000-4000-8000-000000000001'),7,'version rolled back with audit');
select throws_ok($$select pg_temp.catalog_save(7,(select document||'{"variants":[{"id":"c1000000-0000-4000-8000-000000000020","name":"A","sku":null,"priceVnd":1,"stockQuantity":2147483647,"inStock":true,"active":true,"imageUrl":null},{"id":"c1000000-0000-4000-8000-000000000021","name":"B","sku":null,"priceVnd":1,"stockQuantity":1,"inStock":true,"active":true,"imageUrl":null}]}' from catalog_fixture))$$,'22023','CATALOG_INVALID','aggregate overflow is an input error');
select throws_ok($$select pg_temp.catalog_save(7,(select document||jsonb_build_object('images',jsonb_build_array(document->'images'->0,document->'images'->0)) from catalog_fixture))$$,'22023','CATALOG_INVALID','duplicate image IDs rejected inside transaction');
select throws_ok($$select public.save_catalog_product('a0000000-0000-0000-0000-000000000099','b1000000-0000-4000-8000-000000000001',gen_random_uuid(),'c1000000-0000-4000-8000-000000000001',7,(select document from catalog_fixture))$$,'42501','CATALOG_FORBIDDEN','manager cannot choose a foreign organization');
insert into public.products(id,organization_id,source_name,source_url,canonical_url,source_product_id,source_payload,name,in_stock,quality) values('c1000000-0000-4000-8000-000000000002','a0000000-0000-0000-0000-000000000001','GearVN','https://gearvn.com/products/fixture','https://gearvn.com/products/fixture','imported-id','{"fixture":"original source"}','Imported fixture',true,'partial');
insert into public.product_images(id,product_id,source_url,original_source_url) values('c1000000-0000-4000-8000-000000000030','c1000000-0000-4000-8000-000000000002','https://example.invalid/original.jpg','https://example.invalid/original.jpg');
insert into public.product_variants(id,product_id,source_variant_id,options) values('c1000000-0000-4000-8000-000000000031','c1000000-0000-4000-8000-000000000002','original-variant','{"color":"original"}');
select lives_ok($$select public.save_catalog_product('a0000000-0000-0000-0000-000000000001','b1000000-0000-4000-8000-000000000001',gen_random_uuid(),'c1000000-0000-4000-8000-000000000002',1,(select document||'{"images":[{"id":"c1000000-0000-4000-8000-000000000030","url":"https://example.invalid/edited.jpg","altText":null}],"variants":[{"id":"c1000000-0000-4000-8000-000000000031","name":"Edited","sku":null,"priceVnd":10,"stockQuantity":1,"inStock":true,"active":true,"imageUrl":null}]}' from catalog_fixture))$$,'manual imported product update');
select is((select source_name||'/'||source_product_id from public.products where id='c1000000-0000-4000-8000-000000000002'),'GearVN/imported-id','import source remains unchanged');
select is((select source_payload from public.products where id='c1000000-0000-4000-8000-000000000002'),'{"fixture":"original source"}'::jsonb,'original import payload retained');
select is((select original_source_url from public.product_images where id='c1000000-0000-4000-8000-000000000030'),'https://example.invalid/original.jpg','edited image retains original reference');
select is((select source_variant_id from public.product_variants where id='c1000000-0000-4000-8000-000000000031'),'original-variant','variant import identity retained');
select is((select options from public.product_variants where id='c1000000-0000-4000-8000-000000000031'),'{"color":"original"}'::jsonb,'variant source options retained');
reset role;
update public.staff_profiles set active=false where user_id='b1000000-0000-4000-8000-000000000001';
set local role service_role;
select throws_ok($$select pg_temp.catalog_save(7)$$,'42501','CATALOG_FORBIDDEN','fresh disabled profile rejected');
select throws_ok($$select pg_temp.catalog_save(0,null,'d1000000-0000-4000-8000-000000000001')$$,'42501','CATALOG_FORBIDDEN','disabled manager cannot replay');
reset role;
select * from finish();
rollback;
